const urutanArah = ["atas", "kanan", "bawah", "kiri"];

function jalankan(perintah) {
  let x = 0;
  let y = 0;
  let arah = "atas";
  for (let i = 0; i < perintah.length; i++) {
    const p = perintah[i];
    const posisiArah = urutanArah.indexOf(arah);
    if (p === "KANAN") {
      arah = urutanArah[(posisiArah + 1) % 4];
    } else if (p === "KIRI") {
      arah = urutanArah[(posisiArah + 3) % 4];
    } else if (p === "MAJU") {
      if (arah === "atas") y = y + 1;
      else if (arah === "kanan") x = x + 1;
      else if (arah === "bawah") y = y - 1;
      else x = x - 1;
    }
  }
  return { x: x, y: y, arah: arah };
}

