solution.code:
function pecahMateri(mapel) {
  const hasil = [];
  for (let bab = 1; bab <= mapel.jumlahBab; bab++) {
    hasil.push(mapel.nama + " bab " + bab);
  }
  return hasil;
}

function semuaMateri(daftarMapel) {
  const hasil = [];
  for (let i = 0; i < daftarMapel.length; i++) {
    const bab = pecahMateri(daftarMapel[i]);
    for (let j = 0; j < bab.length; j++) {
      hasil.push(bab[j]);
    }
  }
  return hasil;
}

function hariUntuk(i, jumlahHari) {
  return (i % jumlahHari) + 1;
}

function susunJadwal(daftarMapel, jumlahHari) {
  const jadwal = [];
  for (let h = 0; h < jumlahHari; h++) {
    jadwal.push([]);
  }
  const materi = semuaMateri(daftarMapel);
  for (let i = 0; i < materi.length; i++) {
    const hari = hariUntuk(i, jumlahHari);
    jadwal[hari - 1].push(materi[i]);
  }
  return jadwal;
}

function ringkasJadwal(jadwal) {
  const hasil = [];
  for (let h = 0; h < jadwal.length; h++) {
    hasil.push("Hari " + (h + 1) + ": " + jadwal[h].length + " materi");
  }
  return hasil;
}

